#!/usr/bin/env python3
import pathlib,json,csv,html,hashlib,datetime,math
P=pathlib.Path('/Users/imb/Documents/Codex/Analisi-statistica-Xee');R=P/'runs/20261029_original_mass_scan'
rows=json.loads((R/'summary/processed.json').read_text());rows=sorted(rows.values(),key=lambda x:(x['mass'],x['role'],x['era']));status=json.loads((R/'summary/status.json').read_text());inventory=json.loads((R/'input_inventory.json').read_text());masses=sorted(set(a['mass_label'] for a in inventory),key=float)
receipts=[json.loads(p.read_text()) for p in (R/'fits').rglob('receipt.json')];(R/'all_commands_and_receipts.json').write_text(json.dumps(sorted(receipts,key=lambda r:(r['mass'],r['role'],r['era'])),indent=2))
lookup={(r['mass_label'],r['role'],r['era']):r for r in rows};good_sig=[r for r in rows if r['role']=='significance' and r.get('valid')];maxsig=max(good_sig,key=lambda r:r['Z_local']) if good_sig else None
lines=['# Riproduzione originale — scan di massa','','## Configurazione eseguita','','Input: i255 workspace forniti, non modificati. Sono presenti51 masse, da6.0 a11.0GeV con passo0.1GeV. Non sono presenti punti11.1–12.0. Tutti i workspace dichiarano il range di fit6–12GeV e sono stati verificati prima dei fit.','', 'FitDiagnostics eseguito per2022,2022EE,2023,2023BPix e allYears ad ogni massa. Limiti e significanza eseguiti sul combinato allYears. Funzioni, binning, parametri costanti e RooMultiPdf originali preservati; nessun nuovo Chebyshev o parametro introdotto.','', '**Differenza richiesta nei comandi:** solo FitDiagnostics congela le4 normalizzazioni Υ(1S). Limiti e significanza non hanno freezeParameters e quindi profilano quelle normalizzazioni. I risultati dei3 metodi non condividono lo stesso insieme di parametri liberi: questa è una riproduzione dei comandi forniti, non un’armonizzazione.','', 'Sono state aggiunte soltanto le opzioni -m per etichettare gli output con la massa effettiva e -n per separare i file. Minimizzatore strategia0 per tutti; robustFit1 per FitDiagnostics; esplorazione di tutte le combinazioni discrete in FitDiagnostics e Significance, come richiesto. AsymptoticLimits mantiene le opzioni del comando fornito.','', 'Runtime: Combine v11.1.0, commit6c543b6, ROOT6.34.10, Apple Silicon/Pixi. Fino a8 processi concorrenti. Ogni operazione ha una directory distinta, log integrale, comando e ricevuta con durata ed exit code.','', '## Output principali','','- [Limiti osservati e attesi95%CL](plots/limits_vs_mass.png), [PDF](plots/limits_vs_mass.pdf). Asse verticale: r, normalizzazione relativa del segnale nominale del workspace; nessuna conversione in sezione d’urto.','- [p-value locale osservato](plots/pvalue_vs_mass.png), [PDF](plots/pvalue_vs_mass.pdf).','- [Significanza locale](plots/significance_vs_mass.png).','- [Tabella limiti CSV](summary/limits.csv).','- [Tabella significanza e p-value CSV](summary/significance_pvalues.csv).','- [Qualità di tutti i FitDiagnostics CSV](summary/fit_diagnostics.csv).','- [Inventario e checksum degli input](input_inventory.json).','- [Tutti i comandi e ricevute](all_commands_and_receipts.json).','', 'Le significanze sono asintotiche locali: nessuna correzione look-elsewhere. I p-value sono ottenuti da Z tramite la coda normale unilaterale. I punti con output mancanti o non finiti non sono inventati; vengono segnalati nelle tabelle.','', '## Stato di completamento','']
for k,v in status.items():lines.append(f'- `{k}`: {v}')
if maxsig:lines += ['',f"Massimo locale tra i risultati disponibili: massa{maxsig['mass_label']}GeV, Z={maxsig['Z_local']:.5g}, p0={maxsig['p0_local']:.6g}. Questo è il risultato della configurazione originale, non una validazione del modello."]
lines+=['','Un exit code0 non garantisce un fit valido: il CSV distingue status e covQual. Le figure mostrano queste informazioni. Gli output ROOT restano disponibili anche per i fit con avvisi; non sono stati rifatti con impostazioni diverse durante questa riproduzione.','', '## Risultati per massa','','Per ogni FitDiagnostics: ROOT originale, log, PNG/PDF dei fit B e S+B, parametri in CSV e integrali delle componenti dagli istogrammi salvati. Le curve negative sono mostrate in valore assoluto e identificate in legenda. Nessuna banda d’incertezza è aggiunta: il comando non include saveWithUncertainties.','', '| Massa [GeV] | Fit per era | Fit combinato | Limite osservato su r | Z locale | p0 locale |','|---|---|---|---:|---:|---:|']
htmlrows=[]
def quality(r):
 if not r:return 'in attesa'
 if r.get('postprocess_error'):return 'errore lettura'
 if r['exit_code']!=0:return 'errore esecuzione'
 if r['role']=='fitdiagnostics':return f"B:{r.get('b_status','?')}/{r.get('b_covQual','?')}, S+B:{r.get('s_status','?')}/{r.get('s_covQual','?')}"
 return 'ok' if r.get('valid') else 'output incompleto'
for m in masses:
 byera=[]
 for era in ['2022','2022EE','2023','2023BPix']:
  r=lookup.get((m,'fitdiagnostics',era));d=f'fits/mass_{m}/fitdiagnostics/{era}';byera.append(f'[{era}]({d}/fits.pdf)')
  if r:
   report=[f'# Massa{m}GeV — FitDiagnostics {era}','',f"Qualità: {quality(r)}. r={r.get('r')}; errori MINOS lo/hi={r.get('rLoErr')}/{r.get('rHiErr')}.",'', '[Plot](fits.png) · [PDF](fits.pdf) · [Log](combine.log) · [Comando](command.json) · [Parametri](parameters.csv) · [Normalizzazioni dagli istogrammi](normalizations_from_shapes.csv)']
   (R/d/'README.md').write_text('\n'.join(report)+'\n')
 comb=lookup.get((m,'fitdiagnostics','allYears'));lim=lookup.get((m,'limits','allYears'));sig=lookup.get((m,'significance','allYears'));obs=f"{lim['observed']:.6g}" if lim and lim.get('valid') else '—';z=f"{sig['Z_local']:.5g}" if sig and sig.get('valid') else '—';pv=f"{sig['p0_local']:.5g}" if sig and sig.get('valid') else '—';d=f'fits/mass_{m}/fitdiagnostics'
 lines.append(f"| {m} | {' · '.join(byera)} | [PDF]({d}/fits.pdf), {quality(comb)} | {obs} | {z} | {pv} |")
 if comb:(R/d/'README.md').write_text(f"# Massa{m}GeV — FitDiagnostics combinato\n\nQualità: {quality(comb)}. r={comb.get('r')}, errori MINOS lo/hi={comb.get('rLoErr')}/{comb.get('rHiErr')}.\n\n[Plot](fits.png) · [PDF](fits.pdf) · [Log](combine.log) · [Comando](command.json) · [Parametri](parameters.csv) · [Normalizzazioni](normalizations_from_shapes.csv)\n")
 cells=[html.escape(m)]+[' '.join(f'<a href="fits/mass_{m}/fitdiagnostics/{e}/fits.png">{e}</a>' for e in ['2022','2022EE','2023','2023BPix'])]+[f'<a href="{d}/fits.png">plot</a> · <a href="{d}/fits.pdf">PDF</a><br>{html.escape(quality(comb))}',obs,z,pv];htmlrows.append('<tr>'+''.join('<td>'+c+'</td>' for c in cells)+'</tr>')
(R/'README.md').write_text('\n'.join(lines)+'\n')
page='''<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Xee — riproduzione originale</title><style>body{font:15px system-ui;max-width:1250px;margin:35px auto;padding:0 20px;color:#1d2939}h1{font-size:27px}aside{padding:16px;background:#fff4d6;border-left:4px solid #d99900}img{max-width:100%;height:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:left}thead{position:sticky;top:0;background:white}a{color:#1766ba}input{padding:9px;width:250px;margin:20px 0}.plots{display:grid;grid-template-columns:1fr 1fr;gap:20px}code{font-size:13px}</style><h1>Xee — riproduzione dei workspace originali</h1><p>51 masse 6,0–11,0 GeV · fit6–12 GeV · 4 ere e combinato · 357 operazioni</p><aside>Υ(1S) congelata solo in FitDiagnostics; libera per limiti e significanza, come nei comandi forniti. Un comando terminato non garantisce un fit valido: controllare status/covQual. Le significanze sono locali.</aside><p><a href="README.md">Report completo</a> · <a href="summary/all_jobs.csv">Tutti i risultati CSV</a> · <a href="summary/fit_diagnostics.csv">Diagnostica</a></p><div class="plots"><a href="plots/limits_vs_mass.pdf"><img src="plots/limits_vs_mass.png" alt="Limiti"></a><a href="plots/pvalue_vs_mass.pdf"><img src="plots/pvalue_vs_mass.png" alt="p-value locale"></a></div><input id="filter" placeholder="Filtra la massa…"><table><thead><tr><th>Massa</th><th>Fit per era</th><th>Fit combinato (status/covQual)</th><th>Limite osservato r</th><th>Z locale</th><th>p0 locale</th></tr></thead><tbody>'''+''.join(htmlrows)+'''</tbody></table><script>document.getElementById('filter').addEventListener('input',e=>{for(const row of document.querySelectorAll('tbody tr'))row.hidden=!row.cells[0].textContent.includes(e.target.value.trim())})</script></html>'''
(R/'index.html').write_text(page);print(json.dumps(status));print('Index and README generated')
